'use strict';

/**
* Test if a JSON Pointer resolves to a value in a document.
*
* @module @stdlib/utils-json-pointer-has
*
* @example
* var has = require( '@stdlib/utils-json-pointer-has' );
*
* var bool = has( { 'foo': [ 'bar', 'baz' ] }, '/foo/0' );
* // returns true
*
* bool = has( { 'foo': 'bar' }, '/foo' );
* // returns true
*
* bool = has( { 'foo': 'bar' }, '/missing' );
* // returns false
*
* bool = has( { 'foo': 'bar' }, '' );
* // returns true
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
