'use strict';

// MODULES //

var hasOwnProp = require( '@stdlib/assert-has-own-property' );
var resolve = require( '@stdlib/utils-json-pointer-resolve' );


// MAIN //

/**
* Tests if a JSON Pointer resolves to a value in a document.
*
* ## Notes
*
* -   Implements pointer resolution check per RFC 6901.
* -   The function returns `true` if the pointer resolves to an existing property or array element; otherwise, the function returns `false`.
* -   An empty string pointer refers to the root of the document, and the function returns `true` for any valid object or array.
* -   The `-` token on an array references the position after the last element (i.e., a nonexistent element), and, thus, the function returns `false`.
*
* @param {(Object|Array)} document - JSON document
* @param {string} pointer - JSON Pointer string
* @returns {boolean} boolean indicating if a pointer resolves
*
* @example
* var bool = has( { 'foo': [ 'bar', 'baz' ] }, '/foo/0' );
* // returns true
*
* @example
* var bool = has( { 'foo': 'bar' }, '/foo' );
* // returns true
*
* @example
* var bool = has( { 'foo': 'bar' }, '/missing' );
* // returns false
*
* @example
* var bool = has( { 'foo': 'bar' }, '' );
* // returns true
*/
function has( document, pointer ) {
	var res;

	try {
		res = resolve( document, pointer );
	} catch ( err ) { // eslint-disable-line no-unused-vars
		return false;
	}
	if ( res.key === null ) {
		return true;
	}
	return hasOwnProp( res.target, res.key );
}


// EXPORTS //

module.exports = has;
